def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid)
              for c, value in enumerate(row) if value == 2]

    # Use the row containing the most markers as the horizontal backbone.
    counts = {}
    for r, c in points:
        counts[r] = counts.get(r, 0) + 1
    backbone = max(counts, key=lambda r: (counts[r], -r))

    cols = [c for r, c in points]
    for c in range(min(cols), max(cols) + 1):
        if out[backbone][c] == 0:
            out[backbone][c] = 3

    for r, c in points:
        step = 1 if backbone > r else -1
        for rr in range(r + step, backbone, step):
            if out[rr][c] == 0:
                out[rr][c] = 3

    return out
